    map: ['01 - Rotation', 'Rotation de la carte du jour', 'Point d entree quotidien', 'Bureau de rotation', '17 aout 2026', 'Cycle Final Ascent', 'La carte change, mais le plan reste simple : confirmez le parcours, preparez les dangers attendus et gardez une place pour un objet de recuperation.', [['Lire le parcours', 'Confirmez le biome dans le jeu.', 'pret'], ['Preparer la montee', 'Comparez corde, piton et nourriture.', 'plan'], ['Noter le resultat', 'Notez dangers et repos surs.', 'suite']], 'Copier la note de rotation', 'Cycle Final Ascent - confirmer le parcours actif dans PEAK avant de grimper', 'Un parcours de PEAK avec falaises, palmiers et sommet suspendu', 'Capture officielle Steam : le parcours dans le jeu reste la source finale.', ['Pour un joueur de PEAK, la carte du jour est une question pratique. Le parcours decide le temps disponible pour chercher de la nourriture et le materiel qui merite une place.', 'Cette page separe la rotation verifiee de la speculation. Elle n invente pas une graine en direct : le jeu et les annonces officielles restent prioritaires.']],
    updates: ['02 - Version', 'Notes de patch sans bruit', 'Fil officiel', [['AOU', '14', '2026', 'ACTUEL', 'Patch 2.01.a : refroidissement de la grenouille et correctifs', 'Consultez la publication officielle, puis reliez le patch aux dangers, objets et conseils de parcours.'], ['AOU', '12', '2026', 'FONCTION', 'The Final Ascent', 'Un jalon pour organiser les pages de cartes, biomes, equipement et badges.'], ['AOU', '07', '2026', 'ANNONCE', 'La mise a jour du biome final arrive le 11 aout', 'Reliez l annonce aux pages pratiques dont les joueurs ont besoin apres la sortie.']], ['Les pages de mise a jour transforment un pic de recherche en reference durable. Apres un patch, le joueur veut savoir quoi porter et quel parcours a change.', 'Cet instantane utilise les noms et dates officiels. Les explications communautaires doivent etre marquees comme notes de terrain et verifiees dans le jeu.'], 'Illustration officielle PEAK Final Ascent avec des grimpeurs sous le titre PEAK', 'En-tete officiel Steam : contexte de la mise a jour Final Ascent.'],
    database: ['03 - Base de terrain', 'Trouvez le bon objet avant la montee', 'Notes consultables', 'Rechercher objets, nourriture, equipement...', ['Tout', 'Equipement', 'Nourriture', 'Utilite'], 'Aucune note correspondante. Essayez un autre nom ou une autre categorie.', 'Les donnees du prototype restent concises. Les effets, lieux et changements de version doivent etre suivis dans une table de sources.', { gear: 'EQUIPEMENT', utility: 'UTILITE', food: 'NOURRITURE' }, { route: 'parcours', team: 'equipe', coop: 'cooperation', consumable: 'consommable', camp: 'camp', carry: 'charge' }],
    badges: ['04 - Progression', 'Badges et succes au meme endroit', 'PEAK distingue les badges du jeu et les succes de plateforme. La wiki conserve leur condition, leur biome associe et leur source.', [['64', 'succes Steam'], ['4', 'emplacements de biome'], ['1', 'index de progression']], 'Voir la difference dans la FAQ', [['Fiche de succes', 'Etat de completion et nom officiel du succes.'], ['Collection de badges', 'Progression classee par parcours, danger et cooperation.'], ['Contexte cosmetique', 'Reliez chaque recompense a l action qui la debloque.'], ['Historique de version', 'Marquez les fiches touchees par Final Ascent ou un patch.']]],
    guide: ['05 - Notes de terrain', 'Guide cooperatif centre sur les decisions', 'PEAK se comprend mieux comme un probleme d escalade que comme une liste d objets. L equipe choisit quand avancer, qui porte la recuperation et quand un sommet devient un sauvetage.', [['Observer avant de depenser l endurance.', 'Une note de parcours doit expliquer ce qui est visible, pas seulement nommer le biome.'], ['Partager l utilite.', 'Les fiches d objets doivent montrer le role dans l equipe.'], ['Separer faits et experience.', 'Les noms officiels ont une source ; les conseils pratiques ont un contexte.']], ['Les meilleures pages repondent ensemble au jeu solo, au nombre de joueurs et au materiel utile quand un parcours change.', 'La wiki ne commence donc pas par des codes ni par un classement invente. Le besoin tourne autour des parcours, objets, dangers et cooperation.'], 'Des joueurs de PEAK utilisent du materiel d escalade pres d une paroi eclairee par la lave', 'Capture officielle Steam : escalade cooperative et equipement.'],
    faq: ['06 - Reponses rapides', 'FAQ PEAK', 'Intentions de recherche, reponses clairement', [['PEAK se joue-t-il en solo ?', 'Oui. PEAK se joue seul ou en cooperation, avec un groupe allant jusqu a quatre joueurs selon Steam.'], ['PEAK prend-il en charge le crossplay ?', 'Le crossplay peut changer selon les plateformes et les mises a jour. Verifiez la boutique et le patch actuel avant une session mixte.'], ['Combien de joueurs peuvent rejoindre PEAK ?', 'La description officielle Steam indique un groupe de quatre joueurs maximum.'], ['Comment fonctionne la carte quotidienne de PEAK ?', 'PEAK utilise une rotation changeante. Utilisez cette section pour planifier, puis confirmez le parcours dans le jeu.'], ['Ou trouver les notes de patch PEAK ?', 'La section des mises a jour resume 2.01.a et Final Ascent et renvoie au fil officiel Steam.'], ['Les badges PEAK et les succes Steam sont-ils identiques ?', 'Non. Ce sont deux progressions liees, mais elles doivent etre conservees dans des champs separes.']]],
    source: ['Notes des sources', 'Concu pour rester verifiable', 'Cette wiki independante utilise les medias et noms de mises a jour officiels de Steam. Elle n est pas affiliee au developpeur et ne propose pas de telechargement du jeu.'],
    legal: { about: ['A propos de PEAK Game Wiki', 'Comment la wiki independante organise ses notes de cartes, objets, badges, cooperation et mises a jour.', 'A propos du projet', 'Un guide de terrain independant pour PEAK', 'PEAK Game Wiki est un projet de reference centre sur les cartes, objets, badges, cooperation et versions.', [['But de la wiki', 'La premiere version reunit rotations, patchs, equipement, progression et questions de plateforme.'], ['Politique des sources', 'La boutique Steam et les actualites Steam servent de point de depart pour les faits, noms, dates et medias.'], ['Corrections', 'Les informations changent apres les mises a jour. Envoyez une correction accompagnee de sa source via le suivi public.']]], privacy: ['Politique de confidentialite - PEAK Game Wiki', 'Informations sur la confidentialite, les cookies, l analyse et la publicite de PEAK Game Wiki.', 'Confidentialite', 'Confidentialite, cookies et publicite', 'Cette page explique ce qui peut etre traite lors d une visite et comment gerer les preferences.', [['Informations necessaires au site', 'Le site est une reference statique sans compte. Cloudflare Pages peut traiter des donnees techniques pour la livraison et la securite.'], ['Google AdSense et cookies', 'Google et ses partenaires peuvent utiliser des cookies ou identifiants pour mesurer les annonces et proposer une personnalisation lorsque cela est autorise.'], ['Analyse et services externes', 'Microsoft Clarity peut traiter des signaux d interaction. Steam et les autres services appliquent leurs propres politiques.']]], terms: ['Conditions d utilisation - PEAK Game Wiki', 'Conditions, sources, avertissements et usage acceptable de PEAK Game Wiki.', 'Conditions', 'Conditions et limites des sources', 'Utilisez cette reference independante et verifiez les informations sensibles a la version dans le jeu et les sources officielles.', [['Projet independant', 'PEAK Game Wiki est une reference de fans, sans affiliation ni approbation des developpeurs ou de l editeur.'], ['Exactitude et mises a jour', 'Les rotations, objets, succes et compatibilites peuvent changer. Verifiez les informations actuelles avant usage.'], ['Liens externes et usage acceptable', 'Les liens externes menent vers des services tiers. Ne distribuez pas de logiciel malveillant et ne detournez pas les sources du jeu.']]] },
