const requiredKeys = ['meta', 'ui', 'hero', 'signal', 'map', 'updates', 'database', 'badges', 'guide', 'faq', 'source', 'legal', 'items'];
for (const code of localeOrder) {
  const locale = locales[code];
  if (!locale) throw new Error(`Missing locale configuration: ${code}`);
  if (!mapGuides[code]) throw new Error(`Missing map guide configuration: ${code}`);
  if (!todayMapCopy[code]) throw new Error(`Missing today's map copy: ${code}`);
  for (const key of requiredKeys) if (!locale[key]) throw new Error(`Missing ${key} configuration: ${code}`);
  for (const page of ['about', 'privacy', 'terms']) if (!locale.legal[page]) throw new Error(`Missing legal copy: ${code}/${page}`);
  localeMeta[code].copy = locale;
}

function escapeHtml(value) {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function routeFor(code, page) {
  if (code === 'en') return page === 'home' ? '/' : `/${page}`;
  return page === 'home' ? `/${code}/` : `/${code}/${page}/`;
}

function alternateLinks(page) {
  return localeOrder.map((code) => `<link rel="alternate" hreflang="${localeMeta[code].lang}" href="${BASE_URL}${routeFor(code, page)}" />`).concat(`<link rel="alternate" hreflang="x-default" href="${BASE_URL}${routeFor('en', page)}" />`).join('\n    ');
}

function languageMenu(current, page, copy) {
  const links = localeOrder.map((code) => `<a href="${routeFor(code, page)}" hreflang="${localeMeta[code].lang}">${escapeHtml(localeMeta[code].label)}</a>`).join('');
  return `<details class="language-menu"><summary aria-label="${escapeHtml(copy.ui.language)}">${escapeHtml(localeMeta[current].short)} <span aria-hidden="true">\u25be</span></summary><div class="language-menu-list">${links}</div></details>`;
}

function jsonLd(value) {
  return JSON.stringify(value).replace(/</g, '\\u003c');
}

function parseDateValue(value) {
  if (value === null || value === undefined || value === '') return null;
  const source = /^\d{4}-\d{2}-\d{2}$/.test(String(value ?? '')) ? `${value}T00:00:00Z` : value;
  const date = new Date(source);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatDateLabel(locale, value) {
  const date = parseDateValue(value);
  if (!date) return String(value ?? '');
  if (locale === 'de') return new Intl.DateTimeFormat(localeMeta[locale].lang, { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: 'UTC' }).format(date);
  return new Intl.DateTimeFormat(localeMeta[locale].lang, { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }).format(date);
}

export function formatSnapshotDate(locale, buildDate) {
  const date = formatDateLabel(locale, buildDate);
  const formatters = {
    en: (value) => `Snapshot ${value}`,
    zh: (value) => `${value} 快照`,
    es: (value) => `Captura del ${value}`,
    ja: (value) => `${value} 時点`,
    fr: (value) => `Capture du ${value}`,
    de: (value) => `Stand: ${value}`,
    pt: (value) => `Captura de ${value}`,
    ko: (value) => `${value} 기준`,
    it: (value) => `Aggiornato il ${value}`,
  };
  return (formatters[locale] ?? formatters.en)(date);
}

function formatHeroSnapshot(locale, buildDate) {
  const date = formatDateLabel(locale, buildDate);
  const formatters = {
    en: (value) => `Independent PEAK reference - research snapshot ${value}`,
    zh: (value) => `PEAK \u72ec\u7acb\u8d44\u6599 - ${value}\u5feb\u7167`,
    es: (value) => `Referencia independiente de PEAK - instant\u00e1nea del ${value}`,
    ja: (value) => `PEAK \u72ec\u7acb\u53c2\u8003 - ${value}\u306e\u30b9\u30ca\u30c3\u30d7\u30b7\u30e7\u30c3\u30c8`,
    fr: (value) => `R\u00e9f\u00e9rence ind\u00e9pendante PEAK - instantan\u00e9 du ${value}`,
    de: (value) => `Unabh\u00e4ngige PEAK-Referenz - Stand ${value}`,
    pt: (value) => `Refer\u00eancia independente de PEAK - atualizada em ${value}`,
    ko: (value) => `PEAK \ub3c5\ub9bd \ucc38\uace0 \uc790\ub8cc - ${value} \uc2a4\ub0c5\uc0f7`,
    it: (value) => `Riferimento indipendente PEAK - aggiornato il ${value}`,
  };
  return (formatters[locale] ?? formatters.en)(date);
}

function resolveBuildDate(options = {}) {
  return options.buildDate || options.dateModified || process.env.BUILD_DATE || new Date().toISOString().slice(0, 10);
}

function isSafeHttpUrl(value) {
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
}

function isSafeMediaUrl(value) {
  return typeof value === 'string' && (value.startsWith('/') || isSafeHttpUrl(value));
}

function normalizeTodayMap(data, buildDate, buildTimestamp) {
  const source = data?.source;
  const fallbackSource = data?.fallbackSource;
  const hasLocation = [data?.map, data?.route, data?.biome].some((value) => typeof value === 'string' && value.trim());
  const datedSource = data?.date === buildDate && isSafeHttpUrl(source?.url);
  const available = datedSource && hasLocation;
  const mediaValues = Array.isArray(data?.media) ? data.media : data?.media ? [data.media] : [];
  const media = datedSource
    ? mediaValues.filter((item) => item && ['image', 'video'].includes(item.type) && isSafeMediaUrl(item.url))
    : [];
  return {
    available,
    date: datedSource ? data.date : buildDate,
    map: available ? data.map : null,
    route: available ? data.route : null,
    biome: available ? data.biome : null,
    resetAt: datedSource && parseDateValue(data.resetAt) ? data.resetAt : null,
    updatedAt: datedSource ? (data.updatedAt || data.sourceFetchedAt || buildTimestamp) : buildTimestamp,
    source: datedSource ? { label: source.label || '', url: source.url } : null,
    fallbackSource: datedSource && isSafeHttpUrl(fallbackSource?.url) ? { label: fallbackSource.label || '', url: fallbackSource.url } : null,
    media,
  };
}

function formatCountdown(locale, resetAt, buildTimestamp) {
  const resetDate = parseDateValue(resetAt);
  const buildDate = parseDateValue(buildTimestamp);
  const copy = todayMapCopy[locale] ?? todayMapCopy.en;
  if (!resetDate || !buildDate) return copy.resetPending;
  const remainingMinutes = Math.ceil((resetDate.getTime() - buildDate.getTime()) / 60000);
  if (remainingMinutes <= 0) return copy.resetDue;
  const days = Math.floor(remainingMinutes / 1440);
  const hours = Math.floor((remainingMinutes % 1440) / 60);
  const minutes = remainingMinutes % 60;
  const parts = [];
  if (days) parts.push(`${days}${copy.countdownUnits.days}`);
  if (hours || days) parts.push(`${hours}${copy.countdownUnits.hours}`);
  if (minutes || (!days && !hours)) parts.push(`${minutes}${copy.countdownUnits.minutes}`);
  return parts.join(' ');
}

function renderTodayMapMedia(locale, data) {
  const copy = todayMapCopy[locale] ?? todayMapCopy.en;
  if (!data.media.length) {
    return `<div class="today-map-media today-map-media-pending" role="img" aria-label="${escapeHtml(copy.mediaPending)}"><strong>${escapeHtml(copy.mediaPending)}</strong><span>${escapeHtml(copy.mediaPendingNote)}</span></div>`;
  }
  const cards = data.media.map((item, index) => {
    const label = item.biome || `${copy.title} ${index + 1}`;
    const media = item.type === 'video'
      ? `<video controls preload="metadata" width="1200" height="675"><source src="${escapeHtml(item.url)}"${item.mimeType ? ` type="${escapeHtml(item.mimeType)}"` : ''} /></video>`
      : `<img src="${escapeHtml(item.url)}" alt="${escapeHtml(item.alt || label)}" width="1200" height="675" loading="eager" />`;
    const active = index === 0;
    return `<figure id="today-map-slide-${index}" class="today-map-media-card${active ? ' is-active' : ''}" data-carousel-slide role="group" aria-roledescription="slide" aria-label="${index + 1} of ${data.media.length}" aria-hidden="${active ? 'false' : 'true'}">${media}<figcaption><strong>${escapeHtml(label)}</strong><span>${escapeHtml(item.caption || data.source?.label || copy.title)}</span></figcaption></figure>`;
  }).join('');
  const indicators = data.media.map((item, index) => {
    const label = item.biome || `${copy.title} ${index + 1}`;
    return `<button class="today-map-carousel-dot${index === 0 ? ' is-active' : ''}" data-carousel-index="${index}" type="button" aria-pressed="${index === 0 ? 'true' : 'false'}" aria-controls="today-map-slide-${index}" aria-label="Show ${escapeHtml(label)} map"><span aria-hidden="true"></span></button>`;
  }).join('');
  const controls = data.media.length > 1
    ? `<button class="today-map-carousel-arrow today-map-carousel-prev" data-carousel-prev type="button" aria-label="Previous map" title="Previous map"><span aria-hidden="true">\u2190</span></button><button class="today-map-carousel-arrow today-map-carousel-next" data-carousel-next type="button" aria-label="Next map" title="Next map"><span aria-hidden="true">\u2192</span></button>`
    : '';
  return `<div class="today-map-carousel" data-today-carousel tabindex="0" aria-roledescription="carousel" aria-label="${escapeHtml(copy.title)}"><div class="today-map-carousel-viewport"><div class="today-map-carousel-track" data-carousel-track>${cards}</div>${controls}</div><div class="today-map-carousel-dots" role="group" aria-label="Map slides">${indicators}</div></div>`;
}

function renderTodayMap(locale, data, buildDate, buildTimestamp) {
  const copy = todayMapCopy[locale] ?? todayMapCopy.en;
  const snapshot = normalizeTodayMap(data, buildDate, buildTimestamp);
  const mapValue = snapshot.map || copy.pending;
  const routeValue = snapshot.route || copy.pending;
  const biomeValue = snapshot.biome || copy.pending;
  const countdown = formatCountdown(locale, snapshot.resetAt, buildTimestamp);
  const sourceMarkup = snapshot.source
    ? `<a href="${escapeHtml(snapshot.source.url)}" target="_blank" rel="noopener">${escapeHtml(snapshot.source.label || copy.source)} <span aria-hidden="true">\u2192</span></a>${snapshot.fallbackSource ? `<a href="${escapeHtml(snapshot.fallbackSource.url)}" target="_blank" rel="noopener">${escapeHtml(snapshot.fallbackSource.label || copy.source)} <span aria-hidden="true">\u2192</span></a>` : ''}`
    : `<span>${escapeHtml(copy.pending)}</span>`;
  const status = snapshot.available ? copy.verified : copy.pending;
  const panel = snapshot.available
    ? `<h3>${escapeHtml(mapValue)}</h3><p class="today-map-route">${escapeHtml(routeValue)}</p>`
    : `<div class="today-map-pending-copy"><h3>${escapeHtml(copy.pendingTitle)}</h3><p>${escapeHtml(copy.pendingBody)}</p></div>`;
  return `<section id="today-map" class="today-map-section" aria-labelledby="today-map-title"><div class="container today-map-heading"><div><p class="eyebrow">${escapeHtml(copy.eyebrow)}</p><h2 id="today-map-title">${escapeHtml(copy.title)}</h2><p>${escapeHtml(copy.lede)}</p></div><span class="today-map-status${snapshot.available ? ' is-verified' : ''}">${escapeHtml(status)}</span></div><div class="container today-map-grid"><div>${renderTodayMapMedia(locale, snapshot)}</div><div class="today-map-panel"><div class="today-map-panel-top"><span class="status-pill"><i></i>${escapeHtml(status)}</span><time datetime="${escapeHtml(snapshot.date)}">${escapeHtml(formatDateLabel(locale, snapshot.date))}</time></div>${panel}<dl class="today-map-facts"><div><dt>${escapeHtml(copy.currentMap)}</dt><dd>${escapeHtml(mapValue)}</dd></div><div><dt>${escapeHtml(copy.route)}</dt><dd>${escapeHtml(routeValue)}</dd></div><div><dt>${escapeHtml(copy.biome)}</dt><dd>${escapeHtml(biomeValue)}</dd></div><div><dt>${escapeHtml(copy.nextReset)}</dt><dd>${escapeHtml(countdown)}</dd></div></dl><div class="today-map-source"><span>${escapeHtml(copy.source)}</span>${sourceMarkup}</div><p class="today-map-updated"><span>${escapeHtml(copy.updated)}</span> ${escapeHtml(formatDateLabel(locale, snapshot.updatedAt))}</p>${snapshot.available ? '' : `<p class="today-map-note">${escapeHtml(copy.pendingNote)}</p>`}</div></div></section>`;
}

export function injectTodayMapSection(html, locale, data, buildDate, buildTimestamp) {
  const marker = '</section><div class="container article-layout">';
  if (!html.includes(marker)) throw new Error(`Map guide insertion marker not found: ${locale}`);
  return html.replace(marker, `</section>${renderTodayMap(locale, data, buildDate, buildTimestamp)}<div class="container article-layout">`);
}

const articleLinkPages = new Set(['map-rotation', 'achievements', ...articleOrder]);

function renderArticleInline(value, locale, publishedArticles = articleOrder) {
  const source = String(value ?? '');
  const pattern = /\[\[link:([a-z0-9-]+)(#[a-z0-9-]+)?\|([\s\S]*?)\]\]/gi;
  const publishedPages = new Set(['map-rotation', 'achievements', ...publishedArticles]);
  let result = '';
  let cursor = 0;
  for (const match of source.matchAll(pattern)) {
    result += escapeHtml(source.slice(cursor, match.index));
    const page = match[1].toLowerCase();
    if (!articleLinkPages.has(page)) {
      result += escapeHtml(match[0]);
    } else if (!publishedPages.has(page)) {
      result += escapeHtml(match[3]);
    } else {
      const href = `${routeFor(locale, page)}${match[2] || ''}`;
      result += `<a href="${escapeHtml(href)}">${escapeHtml(match[3])}</a>`;
    }
    cursor = match.index + match[0].length;
  }
  return result + escapeHtml(source.slice(cursor));
}

function localizedArticleGuide(locale, slug) {
  const source = articleGuides[slug];
  const translation = articleLocaleTranslations[locale]?.[slug];
  if (!translation) return source;
  const sections = source.sections.map((section, index) => {
    const translated = translation.sections?.[index];
    if (!translated) return section;
    return {
      ...section,
      ...translated,
      table: translated.table ? { ...section.table, ...translated.table } : section.table,
      heroImage: translated.heroImage ? { ...section.heroImage, ...translated.heroImage } : section.heroImage,
    };
  });
  return {
    ...source,
    ...translation,
    meta: { ...source.meta, ...translation.meta },
    heroImage: { ...source.heroImage, ...translation.heroImage },
    sections,
    faq: translation.faq ? { ...source.faq, ...translation.faq } : source.faq,
    source: translation.source ? { ...source.source, ...translation.source } : source.source,
    related: translation.related ?? source.related,
  };
}

function stripArticleTokens(value) {
  return String(value ?? '').replace(/\[\[link:[a-z0-9-]+(?:#[a-z0-9-]+)?\|([\s\S]*?)\]\]/gi, '$1');
}

function renderArticleTable(table, locale, publishedArticles = articleOrder) {
  if (!table) return '';
  const headers = table.headers.map((header) => `<th scope="col">${renderArticleInline(header, locale, publishedArticles)}</th>`).join('');
  const rows = table.rows.map((row) => `<tr>${row.map((cell) => `<td>${renderArticleInline(cell, locale, publishedArticles)}</td>`).join('')}</tr>`).join('');
  return `<div class="article-table-wrap"><table><caption>${renderArticleInline(table.caption, locale, publishedArticles)}</caption><thead><tr>${headers}</tr></thead><tbody>${rows}</tbody></table></div>`;
}

function renderArticleBullets(bullets, locale, publishedArticles = articleOrder) {
  if (!bullets?.length) return '';
  return `<ul class="article-bullets">${bullets.map(([lead, text]) => `<li><strong>${renderArticleInline(lead, locale, publishedArticles)}</strong> ${renderArticleInline(text, locale, publishedArticles)}</li>`).join('')}</ul>`;
}

function renderArticleTodayMap(locale, data, buildDate, buildTimestamp) {
  const copy = articleLiveMapCopy[locale] ?? articleLiveMapCopy.en;
  const snapshot = normalizeTodayMap(data, buildDate, buildTimestamp);
  const status = snapshot.available ? copy.verified : copy.pending;
  const mapValue = snapshot.map || copy.pendingValue;
  const routeValue = snapshot.route === 'Daily biome sequence' ? copy.routeLabel : snapshot.route || copy.pendingValue;
  const biomeValue = snapshot.biome || copy.pendingValue;
  const sourceMarkup = snapshot.source
    ? `<a href="${escapeHtml(snapshot.source.url)}" target="_blank" rel="noopener">${escapeHtml(snapshot.source.label || copy.verifiedSource)} <span aria-hidden="true">\u2192</span></a>`
    : `<span>${escapeHtml(copy.sourcePending)}</span>`;
  const note = snapshot.available
    ? copy.verifiedNote
    : copy.pendingNote;
  return `<div class="article-live-snapshot"><div class="article-live-snapshot-top"><div><p class="eyebrow">${escapeHtml(copy.eyebrow)}</p><h3>${escapeHtml(copy.title)}</h3></div><span class="today-map-status${snapshot.available ? ' is-verified' : ''}">${escapeHtml(status)}</span></div><div class="article-live-snapshot-route"><strong>${escapeHtml(mapValue)}</strong><span>${escapeHtml(routeValue)}</span></div><dl class="article-live-facts"><div><dt>${escapeHtml(copy.biome)}</dt><dd>${escapeHtml(biomeValue)}</dd></div><div><dt>${escapeHtml(copy.recordDate)}</dt><dd><time datetime="${escapeHtml(snapshot.date)}">${escapeHtml(formatDateLabel(locale, snapshot.date))}</time></dd></div><div><dt>${escapeHtml(copy.nextReset)}</dt><dd>${escapeHtml(formatCountdown(locale, snapshot.resetAt, buildTimestamp))}</dd></div></dl><div class="article-live-source"><span>${escapeHtml(copy.source)}</span>${sourceMarkup}</div><p class="article-live-note">${escapeHtml(note)}</p></div>`;
}

function dateKeyAtZone(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const values = Object.fromEntries(parts.filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}`;
}

function timeAtZone(date, timeZone) {
  return new Intl.DateTimeFormat('en-US', { timeZone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(date);
}

function resetDayLabel(date, timeZone) {
  const utcKey = dateKeyAtZone(date, 'UTC');
  const localKey = dateKeyAtZone(date, timeZone);
  if (localKey > utcKey) return ' next day';
  if (localKey < utcKey) return ' previous day';
  return '';
}

function renderArticleResetTimes(section, locale, data, buildDate, buildTimestamp) {
  const snapshot = normalizeTodayMap(data, buildDate, buildTimestamp);
  const resetDate = parseDateValue(snapshot.resetAt);
  const zones = [
    ['UTC', 'UTC', 'Stable source-time reference.'],
    ['China Standard Time (UTC+8)', 'Asia/Shanghai', 'The current record reaches China after midnight.'],
    ['Japan / Korea (UTC+9)', 'Asia/Tokyo', 'Japan and Korea share this offset.'],
    ['Central Europe (summer UTC+2)', 'Europe/Berlin', 'Winter local time is one hour earlier.'],
    ['United Kingdom (summer UTC+1)', 'Europe/London', 'Winter local time is one hour earlier.'],
    ['US Eastern (daylight UTC-4)', 'America/New_York', 'Standard time is one hour earlier.'],
    ['US Pacific (daylight UTC-7)', 'America/Los_Angeles', 'Standard time is one hour earlier.'],
  ];
  const table = resetDate
    ? {
      caption: 'Current build-time reset conversion for the verified map record',
      headers: ['Reference zone', 'Reset time', 'Reading note'],
      rows: zones.map(([label, timeZone, note]) => [label, `${timeAtZone(resetDate, timeZone)}${resetDayLabel(resetDate, timeZone)}`, note]),
    }
    : section.table;
  return renderArticleTable(table, locale);
}

function renderArticleUpdates(locale, data) {
  const copy = articleUpdateCopy[locale] ?? articleUpdateCopy.en;
  const entries = Array.isArray(data?.entries) ? [...data.entries].filter((entry) => entry?.date && entry?.title).sort((left, right) => right.date.localeCompare(left.date)) : [];
  if (!entries.length) return `<p class="article-data-pending">${escapeHtml(copy.empty)}</p>`;
  const rows = entries.map((entry) => {
    const kind = String(entry.kind || 'UPDATE').toUpperCase();
    const summary = copy.summaries?.[entry.title] ?? copy.generic?.[kind] ?? copy.generic?.default ?? entry.summary ?? copy.sourceFallback;
    return `<tr><td><time datetime="${escapeHtml(entry.date)}">${escapeHtml(formatDateLabel(locale, entry.date))}</time></td><td><span class="article-data-tag">${escapeHtml(copy.kind?.[kind] || kind)}</span></td><td><a href="${escapeHtml(entry.url || STEAM_NEWS_URL)}" target="_blank" rel="noopener">${escapeHtml(entry.title)} <span aria-hidden="true">\u2192</span></a></td><td>${escapeHtml(summary)}</td></tr>`;
  }).join('');
  return `<div class="article-table-wrap article-data-table-wrap"><table><caption>${escapeHtml(copy.caption)}</caption><thead><tr><th scope="col">${escapeHtml(copy.date)}</th><th scope="col">${escapeHtml(copy.type)}</th><th scope="col">${escapeHtml(copy.entry)}</th><th scope="col">${escapeHtml(copy.summary)}</th></tr></thead><tbody>${rows}</tbody></table></div><p class="article-data-note">${escapeHtml(copy.note)}</p>`;
}

function renderArticleHistory(locale, data, todayMap, buildDate, buildTimestamp) {
  const history = Array.isArray(data) ? [...data] : [];
  const current = normalizeTodayMap(todayMap, buildDate, buildTimestamp);
  if (current.available && !history.some((entry) => entry?.date === current.date)) {
    history.unshift({ date: current.date, map: current.map, route: current.route, biome: current.biome, resetAt: current.resetAt, source: current.source });
  }
  const entries = history.filter((entry) => entry?.date && (entry.map || entry.route || entry.biome)).sort((left, right) => right.date.localeCompare(left.date)).slice(0, 14);
  if (!entries.length) return '<p class="article-data-pending">No verified rotation records are available for this build.</p>';
  const rows = entries.map((entry) => `<tr><td><time datetime="${escapeHtml(entry.date)}">${escapeHtml(formatDateLabel(locale, entry.date))}</time></td><td>${escapeHtml(entry.map || entry.route || 'Pending')}</td><td>${escapeHtml(entry.biome || 'Pending')}</td><td>${entry.source?.url ? `<a href="${escapeHtml(entry.source.url)}" target="_blank" rel="noopener">${escapeHtml(entry.source.label || 'Verified source')} <span aria-hidden="true">\u2192</span></a>` : 'Source pending'}</td></tr>`).join('');
  return `<div class="article-table-wrap article-data-table-wrap"><table><caption>Recent verified PEAK rotation records</caption><thead><tr><th scope="col">Date</th><th scope="col">Map or sequence</th><th scope="col">Biome context</th><th scope="col">Source</th></tr></thead><tbody>${rows}</tbody></table></div><p class="article-data-note">Rows are appended only when the build source has a matching date and enough location fields to identify the route context. They describe observations, not a guaranteed future cycle.</p>`;
}

